class RenderBuffer {
public:
    static constexpr size_t CHUNK_SIZE = 4096;

    RenderBuffer() : data_(nullptr), capacity_(0), size_(0) {}
    ~RenderBuffer() { if (data_) free(data_); }

    bool allocate(size_t initial_cap) {
        data_ = static_cast<uint8_t*>(malloc(initial_cap));
        if (!data_) return false;
        capacity_ = initial_cap;
        size_ = 0;
        return true;
    }

    bool append(const uint8_t* src, size_t len) {
        if (size_ + len > capacity_) {
            if (!grow(size_ + len)) return false;
        }
        memcpy(data_ + size_, src, len);
        size_ += len;
        return true;
    }

    uint8_t* raw() { return data_; }
    size_t size() const { return size_; }

private:
    bool grow(size_t needed) {
        if (capacity_ == 0) capacity_ = CHUNK_SIZE;
        size_t new_cap = capacity_;
        while (new_cap < needed) {
            // Guard against integer overflow when doubling capacity.
            if (new_cap > (SIZE_MAX / 2)) {
                new_cap = needed;
                break;
            }
            new_cap *= 2;
        }
        uint8_t* new_data = static_cast<uint8_t*>(realloc(data_, new_cap));
        if (!new_data) return false;
        data_ = new_data;
        capacity_ = new_cap;
        return true;
    }

    uint8_t* data_;
    size_t capacity_;
    size_t size_;
};

class StreamObjectParser {
public:
    struct ObjectHeader {
        uint32_t obj_id;
        uint32_t generation;
        uint32_t stream_length;
        uint8_t  filter_type;
    };

    // Parse a cross-reference table entry from uploaded PDF
    // Returns offset into the render pipeline's function table
    static int parse_xref_entry(const uint8_t* data, size_t data_len, size_t offset) {
        if (offset + 20 > data_len) return -1;

        // PDF xref entries are exactly 20 bytes: "nnnnnnnnnn ggggg n \r\n"
        char entry[21];
        memcpy(entry, data + offset, 20);
        entry[20] = '\0';

        // Parse the 10-digit byte offset
        long byte_offset = strtol(entry, nullptr, 10);

        // Parse generation number (digits 11-15)
        long gen_num = strtol(entry + 11, nullptr, 10);

        return static_cast<int>(byte_offset);
    }

    static ObjectHeader parse_object_header(const uint8_t* data, size_t len, size_t pos) {
        ObjectHeader hdr = {};
        if (pos + sizeof(ObjectHeader) > len) return hdr;

        // Read obj_id and generation from stream
        memcpy(&hdr.obj_id, data + pos, 4);
        memcpy(&hdr.generation, data + pos + 4, 4);
        memcpy(&hdr.stream_length, data + pos + 8, 4);
        hdr.filter_type = data[pos + 12];

        return hdr;
    }
};

// Vtable-based rendering pipeline
class IRenderStage {
public:
    virtual ~IRenderStage() = default;
    virtual bool process(RenderBuffer& buf, const uint8_t* input, size_t len) = 0;
    virtual const char* stage_name() const = 0;
};

class DecompressStage : public IRenderStage {
public:
    bool process(RenderBuffer& buf, const uint8_t* input, size_t len) override {
        // Simplified: just copy (real impl would decompress)
        return buf.append(input, len);
    }
    const char* stage_name() const override { return "decompress"; }
};

class RasterizeStage : public IRenderStage {
public:
    bool process(RenderBuffer& buf, const uint8_t* input, size_t len) override {
        return buf.append(input, len);
    }
    const char* stage_name() const override { return "rasterize"; }
};

// The PDF processing pipeline
class PdfProcessor {
public:
    using StageCallback = std::function<bool(RenderBuffer&, const uint8_t*, size_t)>;

    PdfProcessor() {
        stages_.push_back(std::make_unique<DecompressStage>());
        stages_.push_back(std::make_unique<RasterizeStage>());
    }

    bool process_upload(const uint8_t* pdf_data, size_t pdf_len) {
        if (pdf_len < 8) return false;

        // Verify PDF magic
        if (memcmp(pdf_data, "%PDF-", 5) != 0) return false;

        RenderBuffer output;
        if (!output.allocate(RenderBuffer::CHUNK_SIZE)) return false;

        // Find and process stream objects
        size_t pos = 8;
        while (pos < pdf_len - 13) {
            // Look for "stream" keyword
            if (memcmp(pdf_data + pos, "stream", 6) == 0) {
                auto hdr = StreamObjectParser::parse_object_header(
                    pdf_data, pdf_len, pos + 6);

                if (hdr.stream_length == 0) { pos++; continue; }

                size_t stream_start = pos + 6 + 13; // past header

                // Ensure the stream start is within bounds before computing
                // available bytes; otherwise 'avail' would underflow.
                if (stream_start > pdf_len) { pos++; continue; }

                // SAFE: use filter_type as unsigned and bounds-check properly
                size_t stage_idx = static_cast<size_t>(hdr.filter_type);

                if (stage_idx < stages_.size()) {
                    size_t avail = pdf_len - stream_start;
                    size_t to_process = std::min(
                        static_cast<size_t>(hdr.stream_length), avail);

                    // stage_idx is guaranteed to be within [0, stages_.size())
                    // because it's size_t (unsigned) and checked < size()
                    stages_[stage_idx]->process(output, 
                        pdf_data + stream_start, to_process);
                }
            }
            pos++;
        }

        return output.size() > 0;
    }

private:
    std::vector<std::unique_ptr<IRenderStage>> stages_;
};

} // namespace pdfgen

int main(int argc, char* argv[]) {
    if (argc < 2) {
        std::cerr << "Usage: pdfgen <input.pdf>" << std::endl;
        return 1;
    }

    std::ifstream file(argv[1], std::ios::binary | std::ios::ate);
    if (!file.is_open()) {
        std::cerr << "Cannot open file" << std::endl;
        return 1;
    }

    size_t file_size = file.tellg();
    if (file_size > 10 * 1024 * 1024) {
        std::cerr << "File too large" << std::endl;
        return 1;
    }

    file.seekg(0);
    std::vector<uint8_t> data(file_size);
    file.read(reinterpret_cast<char*>(data.data()), file_size);

    pdfgen::PdfProcessor processor;
    if (processor.process_upload(data.data(), data.size())) {
        std::cout << "PDF processed successfully" << std::endl;
    } else {
        std::cerr << "PDF processing failed" << std::endl;
    }

    return 0;
}
